const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/punch_item_assignments/%7Bid%7D',
  headers: {
    Authorization: 'Bearer REPLACE_BEARER_TOKEN',
    'content-type': 'multipart/form-data; boundary=---011000010111000001101001'
  },
  formData: {
    send_emails: 'true',
    punch_item_assignment: '{"approved":true,"comment":"This Punch Item task is complete","login_information_id":421}',
    attachments: '["<file.png>"]'
